const INPUTS = {
  stageB: path.join(TECH, "02_仓位完整操作链.csv"),
  stageC: path.join(TECH, "03_条件委托演变链.csv"),
  stageCSummary: path.join(TECH, "03_条件委托逐笔汇总.csv"),
  stageD: path.join(TECH, "04_资金估算结果.csv"),
  stageDEvents: path.join(TECH, "04_资金事件归属明细.csv"),
  stageE: path.join(TECH, "05_逐笔复盘汇总.csv"),
  stageEMapping: path.join(TECH, "05_人工复盘字段映射.csv"),
};

async function loadAllData() {
  const entries = await Promise.all(
    Object.entries(INPUTS).map(async ([key, filePath]) => [
      key,
      await readCsv(filePath),
    ]),
  );
  return Object.fromEntries(entries);

