async function importWorkbook(filePath) {
  return SpreadsheetFile.importXlsx(await FileBlob.load(filePath));

const workbook = await importWorkbook(mother);
const sheetInspect = await workbook.inspect({
  kind: "workbook,sheet,definedName",
  include: "id,name,state,visibility,formula,range",
  maxChars: 30000,
});
await fs.writeFile(
  path.join(baselineDir, "M4-F2_母版工作簿结构_artifact.ndjson"),
